SELECT m.id,e.id AS event_id,e.date AS event_start_date,e.name,e.type,e.surface,m.round,m.winner,w.name AS winner_name,m.loser,l.name AS loser_name,m.score,m.status FROM matches m JOIN events e ON e.id=m.event JOIN players w ON w.id=m.winner JOIN players l ON l.id=m.loser WHERE (m.winner=%s OR m.loser=%s) AND e.date<=%s AND m.status='Completed' ORDER BY e.date DESC,CASE m.round WHEN 'F' THEN 10 WHEN 'SF' THEN 9 WHEN 'QF' THEN 8 WHEN 'R16' THEN 7 WHEN 'R32' THEN 6 WHEN 'R64' THEN 5 WHEN 'R128' THEN 4 WHEN 'Q3' THEN 3 WHEN 'Q2' THEN 2 WHEN 'Q1' THEN 1 ELSE 0 END DESC,m.id DESC LIMIT 10